// FUNCTION: BFME2 0x005DB3B3 size=351 name=?UpdateSlotName@AptConnectionScreen@@QAEXH@Z evidence=N:ledger tier=A
void AptConnectionScreen::UpdateSlotName(int slot)
{
	if (TheGameSpyInfo == 0)
		return;
	GameInfo *game = (GameInfo *)TheGameSpyInfo->getCurrentStagingRoom();
	if (game == 0)
		return;
	GameSlot *gameSlot = game->getSlot(slot);
	if (gameSlot == 0)
		return;
	AsciiString key;
	key.format("APT:ConnectionPlayerName_%d", slot);
	UnicodeString text(gameSlot->m_name);
	if (gameSlot->isHuman())
		g_bfmeAptWindowManager->bfmeSetText(key, gameSlot->m_name, false);
	else
		g_bfmeAptWindowManager->bfmeSetText(key, UnicodeString(L" "), false);
	key.format("APT:ConnectionPlayerNum_%d", slot);
	if (gameSlot->isHuman())
	{
		text.format(L"%d.", slot + 1);
		g_bfmeAptWindowManager->bfmeSetText(key, text, false);
	}
	else
		g_bfmeAptWindowManager->bfmeSetText(key, UnicodeString(L" "), false);
}

